solution:
async function reduceAsync(arr, fn, init) {
  let acc = init;
  for (const item of arr) acc = await fn(acc, item);
  return acc;
}
reduceAsync([1, 2, 3], async (a, b) => a + b, 0)
  .then(r => console.log(r));
